                for check in deployment_checks
                if check.get("operator_id") == conflict.get("operator_id")
                and check.get("frame") == conflict.get("frame")
            ),
            None,
        )
        conflict_frame = conflict.get("frame")
        previous_economic_events = [
            {
                "event": row.get("event"),
